=\"end\" transform=\"translate(67.37748718261719 228)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">20</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"79.37748718261719\" y1=\"247\" x2=\"435\" y2=\"247\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"73.37748718261719\" y1=\"247\" x2=\"85.37748718261719\" y2=\"247\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text text-anchor=\"end\" transform=\"translate(67.37748718261719 253)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">10</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"79.37748718261719\" y1=\"272\" x2=\"435\" y2=\"272\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"73.37748718261719\" y1=\"272\" x2=\"85.37748718261719\" y2=\"272\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text text-anchor=\"end\" transform=\"translate(67.37748718261719 278)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">0</text><text text-anchor=\"middle\" transform=\"translate(24 172) rotate(-90)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">Percent</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"79.37748718261719\" y1=\"72\" x2=\"79.37748718261719\" y2=\"272\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"109.01269658406575\" x2=\"109.01269658406575\" y1=\"72\" y2=\"272\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text xmlns=\"http://www.w3.org/2000/svg\" x=\"0\" y=\"0\" text-anchor=\"end\" transform=\"translate(118.93269658406575 291.84) rotate(-40)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">1953</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"168.2831153869629\" x2=\"168.2831153869629\" y1=\"72\" y2=\"272\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text xmlns=\"http://www.w3.org/2000/svg\" x=\"0\" y=\"0\" text-anchor=\"end\" transform=\"translate(178.20311538696288 291.84) rotate(-40)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">1973</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"227.55353418986002\" x2=\"227.55353418986002\" y1=\"72\" y2=\"272\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text xmlns=\"http://www.w3.org/2000/svg\" x=\"0\" y=\"0\" text-anchor=\"end\" transform=\"translate(237.47353418986 291.84) rotate(-40)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">1993</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"286.82395299275714\" x2=\"286.82395299275714\" y1=\"72\" y2=\"272\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text xmlns=\"http://www.w3.org/2000/svg\" x=\"0\" y=\"0\" text-anchor=\"end\" transform=\"translate(296.74395299275716 291.84) rotate(-40)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">2003</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"346.0943717956543\" x2=\"346.0943717956543\" y1=\"72\" y2=\"272\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text xmlns=\"http://www.w3.org/2000/svg\" x=\"0\" y=\"0\" text-anchor=\"end\" transform=\"translate(356.0143717956543 291.84) rotate(-40)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">2013</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"405.36479059855145\" x2=\"405.36479059855145\" y1=\"72\" y2=\"272\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text xmlns=\"http://www.w3.org/2000/svg\" x=\"0\" y=\"0\" text-anchor=\"end\" transform=\"translate(415.28479059855147 291.84) rotate(-40)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">2023</text><text text-anchor=\"middle\" transform=\"translate(257.1887435913086 24)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">Percentage of US Congress Members Who</text><text text-anchor=\"middle\" transform=\"translate(257.1887435913086 48)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">Self-Identified as Veterans, 1953–2023</text><text text-anchor=\"middle\" transform=\"translate(257.1887435913086 350.42251953125)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">Year</text><rect xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" x=\"93.14979553222656\" y=\"367.58251953125\" height=\"71\" width=\"278.7004089355469\" stroke=\"#000000\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><line x1=\"100.14979553222656\" y1=\"384.58251953125\" x2=\"127.14979553222656\" y2=\"384.58251953125\" stroke=\"#000\" stroke-width=\"2.4\" marker-end=\"url(#marker0)\"/><line x1=\"127.14979553222656\" y1=\"384.58251953125\" x2=\"154.14979553222656\" y2=\"384.58251953125\" stroke=\"#000\" stroke-width=\"2.4\" marker-start=\"url(#marker0)\"/><text transform=\"translate(164.14979553222656 391.58251953125)\" text-anchor=\"top\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\"> House of Representatives</text><line x1=\"100.14979553222656\" y1=\"416.58251953125\" x2=\"127.14979553222656\" y2=\"416.58251953125\" stroke=\"#000\" stroke-width=\"2.4\" stroke-dasharray=\"9 6\" marker-end=\"url(#marker1)\"/><line x1=\"127.14979553222656\" y1=\"416.58251953125\" x2=\"154.14979553222656\" y2=\"416.58251953125\" stroke=\"#000\" stroke-width=\"2.4\" stroke-dasharray=\"9 6\" marker-start=\"url(#marker1)\"/><text transform=\"translate(164.14979553222656 423.58251953125)\" text-anchor=\"top\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\"> Senate</text><line x1=\"109.01269658406575\" y1=\"117\" x2=\"168.2831153869629\" y2=\"87\" stroke=\"#000\" stroke-width=\"2.4\" marker-end=\"url(#marker0)\" marker-start=\"url(#marker0)\"/><line x1=\"109.01269658406575\" y1=\"87\" x2=\"168.2831153869629\" y2=\"74.5\" stroke=\"#000\" stroke-width=\"2.4\" stroke-dasharray=\"9 6\" marker-end=\"url(#marker1)\" marker-start=\"url(#marker1)\"/><line x1=\"168.2831153869629\" y1=\"87\" x2=\"227.55353418986002\" y2=\"172\" stroke=\"#000\" stroke-width=\"2.4\" marker-end=\"url(#marker0)\" marker-start=\"url(#marker0)\"/><line x1=\"168.2831153869629\" y1=\"74.5\" x2=\"227.55353418986002\" y2=\"114.5\" stroke=\"#000\" stroke-width=\"2.4\" stroke-dasharray=\"9 6\" marker-end=\"url(#marker1)\" marker-start=\"url(#marker1)\"/><line x1=\"227.55353418986002\" y1=\"172\" x2=\"286.82395299275714\" y2=\"214.5\" stroke=\"#000\" stroke-width=\"2.4\" marker-end=\"url(#marker0)\" marker-start=\"url(#marker0)\"/><line x1=\"227.55353418986002\" y1=\"114.5\" x2=\"286.82395299275714\" y2=\"184.5\" stroke=\"#000\" stroke-width=\"2.4\" stroke-dasharray=\"9 6\" marker-end=\"url(#marker1)\" marker-start=\"url(#marker1)\"/><line x1=\"286.82395299275714\" y1=\"214.5\" x2=\"346.0943717956543\" y2=\"228.5\" stroke=\"#000\" stroke-width=\"2.4\" marker-end=\"url(#marker0)\" marker-start=\"url(#marker0)\"/><line x1=\"286.82395299275714\" y1=\"184.5\" x2=\"346.0943717956543\" y2=\"227\" stroke=\"#000\" stroke-width=\"2.4\" stroke-dasharray=\"9 6\" marker-end=\"url(#marker1)\" marker-start=\"url(#marker1)\"/><line x1=\"346.0943717956543\" y1=\"228.5\" x2=\"405.36479059855145\" y2=\"226\" stroke=\"#000\" stroke-width=\"2.4\" marker-end=\"url(#marker0)\" marker-start=\"url(#marker0)\"/><line x1=\"346.0943717956543\" y1=\"227\" x2=\"405.36479059855145\" y2=\"229.5\" stroke=\"#000\" stroke-width=\"2.4\" stroke-dasharray=\"9 6\" marker-end=\"url(#marker1)\" marker-start=\"url(#marker1)\"/></g></svg></figure><div class=\"sr-only\" role=\"region\" aria-label=\"Long description for line graph titled Percentage of US Congress Members Who Self-Identified as Veterans, 1953–2023\"><ul>\n<li>All values are approximate.</li>\n<li>The following 2 lines are shown:<br/>\n<ul>\n<li>House of Representatives</li>\n<li>Senate</li>\n</ul>\n</li>\n<li>The House of Representatives line:<br/>\n<ul>\n<li>Begins at 1953, 62%</li>\n<li>Rises sharply to 1973, 74%</li>\n<li>Falls sharply to 1993, 40%</li>\n<li>Falls sharply to 2003, 23%</li>\n<li>Falls gradually to 2013, 17%</li>\n<li>Rises gradually to 2023, 18%</li>\n</ul>\n</li>\n<li>The Senate line:&nbsp;<br/>\n<ul>\n<li>Begins at 1953, 74%</li>\n<li>Rises gradually to 1973, 79%</li>\n<li>Falls sharply to 1993, 63%</li>\n<li>Falls sharply to 2003, 35%</li>\n<li>Falls sharply to 2013, 18%</li>\n<li>Falls gradually to 2023, 17%</li>\n</ul>\n</li>\n</ul></div>\n<p>Since the nation&rsquo;s earliest days, both houses of the United States Congress have counted many military veterans among their elected officials, including Hiram <span data-ssml-sub-alias=\"L\">L.</span> Fong (who served in the US Army Air Force) and Ralph Harold Metcalfe <span data-ssml-sub-alias=\"Sr\">Sr.</span> (who served in the US Army). A research institute gathered historical data about congressional members who have reported past military experience and determined that <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most effectively uses data from the graph to complete the sentence?</p>","answerOptions":[{"id":"a86bf56a-37db-420f-a33d-aa6d888880a4","content":"<p>from <span data-ssml-say-as=\"date\">2003</span> to <span data-ssml-say-as=\"date\">2023</span>, the House of Representatives had a higher percentage of those members than the Senate did.</p>"},{"id":"80d11ea0-2582-4668-835f-8c1a48f73ada","content":"<p>from <span data-ssml-say-as=\"date\">1953</span> to <span data-ssml-say-as=\"date\">2003</span>, those members constituted a majority in both houses of Congress.</p>"},{"id":"9e8ab91a-f0ef-40a9-be6d-0f45b62dafeb","content":"<p>the percentage of those members decreased substantially in both houses of Congress from <span data-ssml-say-as=\"date\">1973</span> to <span data-ssml-say-as=\"date\">2013</span>.</p>"},{"id":"a10094a6-5dfa-4422-bdee-921d90a53b78","content":"<p>the percentage of those members remained fairly consistent, regardless of house, from <span data-ssml-say-as=\"date\">1993</span> to <span data-ssml-say-as=\"date\">2023</span>.</p>"}],"keys":["9e8ab91a-f0ef-40a9-be6d-0f45b62dafeb"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it accurately uses data from the graph to complete the statement regarding the research institute&rsquo;s findings about veteran representation in Congress. The graph shows that the percentage of veterans in both houses of Congress decreased dramatically from 1973 to 2013. In 1973, the House of Representatives consisted of approximately 74% veterans, and the Senate was made up of approximately 79% veterans. By 2013, veteran members of both houses had fallen to approximately 17%&ndash;18%. This represents a substantial decrease of more than 50% in each house over this 40-year period.</p><p>Choice A is incorrect because from 2003 to 2023, the House of Representatives did not consistently have a higher percentage of veterans than the Senate did. According to the graph, in 2003 the Senate was made up of approximately 35% veterans, while the House consisted of approximately 23% veterans. In 2013, the number of veterans in the Senate was still slightly higher (approximately 18%) than in the House (approximately 17%). Only in 2023 did the House have a marginally higher percentage than the Senate. Choice B is incorrect because veterans did not constitute a majority in both houses throughout the entire period shown in the graph from 1953 to 2003. According to the graph, both houses had a majority of veterans in 1953 (approximately 62% in the House and approximately 74% in the Senate) and in 1973 (approximately 74% in the House and approximately 79% in the Senate), but by 1993 the House had fallen below 50% to approximately 40% veterans. By 2003, both houses were well below 50%. Choice D is incorrect because the percentage of veterans in Congress did not remain consistent from 1993 to 2023. The graph shows significant changes in the number of members reporting past military service during this period, particularly the continued decline from 1993 to 2003. In 1993, the House had approximately 40% veterans and the Senate had approximately 63% veterans, but by 2003 these percentages had dropped to approximately 23% and 35%, respectively. Furthermore, there was a large gap between the two houses in 1993 that narrowed considerably by 2013, which contradicts the claim that the percentage of veterans across both houses &ldquo;remained fairly consistent&rdquo; during this period.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1776362771168,"updateDate":1776362771168}$SATQ$::jsonb, 1776362771168, 1776362771168),
    ($SATQ$3f05e40f$SATQ$, $SATQ$7e4e4382-e8f2-4072-ab9e-42dfb93b9837$SATQ$::uuid, $SATQ$ae7889a4-5779-4c55-ba21-ba877b8fa2c7$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$CID$SATQ$, $SATQ$Central Ideas and Details$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>In many of his sculptures, artist Richard Hunt uses broad forms rather than extreme accuracy to hint at specific people or ideas. In his first major work,<em> Arachne</em> (1956), Hunt constructed the mythical character Arachne, a weaver who was changed into a spider, by welding bits of steel together into something that, although vaguely human, is strange and machine-like. And his large bronze sculpture <em>The Light of Truth</em> (2021) commemorates activist and journalist Ida B. Wells using mainly flowing, curved pieces of metal that create stylized flame.</p>$SATQ$, $SATQ$<p>Which choice best states the text&rsquo;s main idea about Hunt?</p>$SATQ$, $SATQ$[{"id":"7dbfe9b0-80f7-48b2-8c8d-130e6de026d6","content":"<p>He often depicts the subjects of his sculptures using an unrealistic style.</p>"},{"id":"2621c707-4962-4aa7-babe-17c3a5326db9","content":"<p>He uses different kinds of materials depending on what kind of sculpture he plans to create.</p>"},{"id":"2b21a069-4809-4572-a296-2499d7db6021","content":"<p>He tends to base his art on important historical figures rather than on fictional characters.</p>"},{"id":"ff1173b9-90c7-42a2-b2ac-1ed0b7ed8dc6","content":"<p>He has altered his approach to sculpture over time, and his works have become increasingly abstract.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["7dbfe9b0-80f7-48b2-8c8d-130e6de026d6"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it most accurately states the main idea of the text. According to the text, many of Richard Hunt&rsquo;s sculptures &ldquo;use broad forms rather than extreme accuracy&rdquo;&mdash;in other words, they are more abstract than realistic. To illustrate Hunt&rsquo;s abstract approach, the text characterizes his sculpture of Arachne as &ldquo;vaguely human&rdquo; and his work in honor of Ida B. Wells as &ldquo;using mainly flowing, curved pieces of metal that create stylized flame.&rdquo; Thus, the main idea is that Hunt often depicts the subjects of his sculptures using an unrealistic style. </p><p>Choice B is incorrect. Although the text indicates that one of Hunt&rsquo;s sculptures is made of steel and another of bronze, there is no mention of why he chose these materials. Choice C is incorrect because the text says nothing about how Hunt chose the subjects for his sculptures. Furthermore, of the two examples provided in the text, only Ida B. Wells is an important historical figure; Arachne is a &ldquo;mythical character.&rdquo; Choice D is incorrect because the text says nothing about how Hunt&rsquo;s style changed over time. In fact, although the two examples of Hunt&rsquo;s work discussed in the text were created 65 years apart, they are both described as heavily stylized rather than realistic, which may suggest that some aspects of Hunt&rsquo;s style haven&rsquo;t changed over that time. </p>$SATQ$, false, 0, $SATQ$OSP-KA-CID-M002$SATQ$, $SATQ$$SATQ$, $SATQ$67427a20-2752-4c71-b5cc-c8d000862e4a$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"3f05e40f","external_id":"7e4e4382-e8f2-4072-ab9e-42dfb93b9837","vaultid":"ae7889a4-5779-4c55-ba21-ba877b8fa2c7","uId":"89ffeaed-addf-4c97-881f-ffab0e81d3bc","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"CID","skill_desc":"Central Ideas and Details","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>In many of his sculptures, artist Richard Hunt uses broad forms rather than extreme accuracy to hint at specific people or ideas. In his first major work,<em> Arachne</em> (1956), Hunt constructed the mythical character Arachne, a weaver who was changed into a spider, by welding bits of steel together into something that, although vaguely human, is strange and machine-like. And his large bronze sculpture <em>The Light of Truth</em> (2021) commemorates activist and journalist Ida B. Wells using mainly flowing, curved pieces of metal that create stylized flame.</p>","stem":"<p>Which choice best states the text&rsquo;s main idea about Hunt?</p>","answerOptions":[{"id":"7dbfe9b0-80f7-48b2-8c8d-130e6de026d6","content":"<p>He often depicts the subjects of his sculptures using an unrealistic style.</p>"},{"id":"2621c707-4962-4aa7-babe-17c3a5326db9","content":"<p>He uses different kinds of materials depending on what kind of sculpture he plans to create.</p>"},{"id":"2b21a069-4809-4572-a296-2499d7db6021","content":"<p>He tends to base his art on important historical figures rather than on fictional characters.</p>"},{"id":"ff1173b9-90c7-42a2-b2ac-1ed0b7ed8dc6","content":"<p>He has altered his approach to sculpture over time, and his works have become increasingly abstract.</p>"}],"keys":["7dbfe9b0-80f7-48b2-8c8d-130e6de026d6"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it most accurately states the main idea of the text. According to the text, many of Richard Hunt&rsquo;s sculptures &ldquo;use broad forms rather than extreme accuracy&rdquo;&mdash;in other words, they are more abstract than realistic. To illustrate Hunt&rsquo;s abstract approach, the text characterizes his sculpture of Arachne as &ldquo;vaguely human&rdquo; and his work in honor of Ida B. Wells as &ldquo;using mainly flowing, curved pieces of metal that create stylized flame.&rdquo; Thus, the main idea is that Hunt often depicts the subjects of his sculptures using an unrealistic style. </p><p>Choice B is incorrect. Although the text indicates that one of Hunt&rsquo;s sculptures is made of steel and another of bronze, there is no mention of why he chose these materials. Choice C is incorrect because the text says nothing about how Hunt chose the subjects for his sculptures. Furthermore, of the two examples provided in the text, only Ida B. Wells is an important historical figure; Arachne is a &ldquo;mythical character.&rdquo; Choice D is incorrect because the text says nothing about how Hunt&rsquo;s style changed over time. In fact, although the two examples of Hunt&rsquo;s work discussed in the text were created 65 years apart, they are both described as heavily stylized rather than realistic, which may suggest that some aspects of Hunt&rsquo;s style haven&rsquo;t changed over that time. </p>","parenttemplatename":"OSP-KA-CID-M002","parenttemplateid":"","templateclusterid":"67427a20-2752-4c71-b5cc-c8d000862e4a","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959360,"updateDate":1691007959360}$SATQ$::jsonb, 1691007959360, 1691007959360),
    ($SATQ$3f236877$SATQ$, $SATQ$280e894c-bee8-4e44-8ecc-445ed3d14286$SATQ$::uuid, $SATQ$a1ddc5b3-0f71-4c14-850a-3540355234d1$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>Ratified by more than 90 countries, the Nagoya Protocol is an international agreement ensuring that Indigenous communities are compensated when their agricultural resources and knowledge of wild plants and animals are utilized by agricultural corporations. However, the protocol has shortcomings. For example, it allows corporations to insist that their agreements with communities to conduct research on the commercial uses of the communities&rsquo; resources and knowledge remain confidential. Therefore, some Indigenous advocates express concern that the protocol may have the unintended effect of <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"85c9e71d-8f84-4ae2-b487-68e5a1cc7828","content":"<p>diminishing the monetary reward that corporations might derive from their agreements with Indigenous communities.</p>"},{"id":"094252ba-bf6f-4a55-a2df-ee1242e6bbd1","content":"<p>limiting the research that corporations conduct on the resources of the Indigenous communities with which they have signed agreements.</p>"},{"id":"0f838d65-af28-4590-bb5e-903e022620e3","content":"<p>preventing independent observers from determining whether the agreements guarantee equitable compensation for Indigenous communities.</p>"},{"id":"699c1560-5aae-451c-8277-b066920076a5","content":"<p>discouraging Indigenous communities from learning new methods for harvesting plants and animals from their corporate partners.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["0f838d65-af28-4590-bb5e-903e022620e3"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it most logically completes the argument about an unintended effect of the Nagoya Protocol. The text explains that the Nagoya Protocol is an agreement ensuring that Indigenous communities are compensated when their agricultural resources and knowledge are used by corporations. The text then states that the protocol allows corporations to keep their agreements with Indigenous communities confidential, about which some Indigenous advocates express concern. Choice C, when inserted into the blank, gives a good justification for the advocates&rsquo; concern: such secrecy could mean that the public is unable to determine whether participating Indigenous communities were properly compensated under these agreements.&nbsp;</p><p>Choice A is incorrect. The text suggests that because corporations can keep their agreements with Indigenous communities confidential, Indigenous communities, not corporations, might not be compensated fairly.&nbsp;Choice B is incorrect because the text doesn&rsquo;t suggest that the ability of corporations to keep their agreements with Indigenous communities confidential would place limits on how much research corporations can undertake.&nbsp;Choice D is incorrect because the text doesn&rsquo;t indicate that Indigenous communities aim to learn new harvesting methods from their corporate partners. Rather, the text suggests that corporations use the knowledge of Indigenous communities for their research. </p>$SATQ$, false, 0, $SATQ$OSP-033-INF$SATQ$, $SATQ$$SATQ$, $SATQ$cc8cae73-2886-487f-b37e-c63d85bed2b5$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"3f236877","external_id":"280e894c-bee8-4e44-8ecc-445ed3d14286","vaultid":"a1ddc5b3-0f71-4c14-850a-3540355234d1","uId":"73032803-1f3f-479f-97f9-0d7aa2305354","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>Ratified by more than 90 countries, the Nagoya Protocol is an international agreement ensuring that Indigenous communities are compensated when their agricultural resources and knowledge of wild plants and animals are utilized by agricultural corporations. However, the protocol has shortcomings. For example, it allows corporations to insist that their agreements with communities to conduct research on the commercial uses of the communities&rsquo; resources and knowledge remain confidential. Therefore, some Indigenous advocates express concern that the protocol may have the unintended effect of <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"85c9e71d-8f84-4ae2-b487-68e5a1cc7828","content":"<p>diminishing the monetary reward that corporations might derive from their agreements with Indigenous communities.</p>"},{"id":"094252ba-bf6f-4a55-a2df-ee1242e6bbd1","content":"<p>limiting the research that corporations conduct on the resources of the Indigenous communities with which they have signed agreements.</p>"},{"id":"0f838d65-af28-4590-bb5e-903e022620e3","content":"<p>preventing independent observers from determining whether the agreements guarantee equitable compensation for Indigenous communities.</p>"},{"id":"699c1560-5aae-451c-8277-b066920076a5","content":"<p>discouraging Indigenous communities from learning new methods for harvesting plants and animals from their corporate partners.</p>"}],"keys":["0f838d65-af28-4590-bb5e-903e022620e3"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it most logically completes the argument about an unintended effect of the Nagoya Protocol. The text explains that the Nagoya Protocol is an agreement ensuring that Indigenous communities are compensated when their agricultural resources and knowledge are used by corporations. The text then states that the protocol allows corporations to keep their agreements with Indigenous communities confidential, about which some Indigenous advocates express concern. Choice C, when inserted into the blank, gives a good justification for the advocates&rsquo; concern: such secrecy could mean that the public is unable to determine whether participating Indigenous communities were properly compensated under these agreements.&nbsp;</p><p>Choice A is incorrect. The text suggests that because corporations can keep their agreements with Indigenous communities confidential, Indigenous communities, not corporations, might not be compensated fairly.&nbsp;Choice B is incorrect because the text doesn&rsquo;t suggest that the ability of corporations to keep their agreements with Indigenous communities confidential would place limits on how much research corporations can undertake.&nbsp;Choice D is incorrect because the text doesn&rsquo;t indicate that Indigenous communities aim to learn new harvesting methods from their corporate partners. Rather, the text suggests that corporations use the knowledge of Indigenous communities for their research. </p>","parenttemplatename":"OSP-033-INF","parenttemplateid":"","templateclusterid":"cc8cae73-2886-487f-b37e-c63d85bed2b5","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959319,"updateDate":1691007959319}$SATQ$::jsonb, 1691007959319, 1691007959319),
    ($SATQ$3f4ab688$SATQ$, $SATQ$8ce518f3-dd51-4bc0-8eb6-72b9a8219145$SATQ$::uuid, $SATQ$a41c8c55-34f2-4866-a06f-52e6044f56e9$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>In a research paper, a student criticizes some historians of modern African politics, claiming that they have evaluated Patrice Lumumba, the first prime minister of what is now the Democratic Republic of the Congo, primarily as a symbol rather than in terms of his actions. </p>$SATQ$, $SATQ$<p>Which quotation from a work by a historian would best illustrate the student&rsquo;s claim?</p>$SATQ$, $SATQ$[{"id":"0016e186-bd95-482b-bed8-5d55908c036e","content":"<p>&ldquo;Lumumba is a difficult figure to evaluate due to the starkly conflicting opinions he inspired during his life and continues to inspire today.&rdquo;</p>"},{"id":"e835e8ba-6a6f-4f7f-b1aa-8d18567b9627","content":"<p>&ldquo;The available information makes it clear that Lumumba&rsquo;s political beliefs and values were largely consistent throughout his career.&rdquo;</p>"},{"id":"1f5290cc-1138-4db1-aafe-3a23129cdca3","content":"<p>&ldquo;Lumumba&rsquo;s practical accomplishments can be passed over quickly; it is mainly as the personification of Congolese independence that he warrants scholarly attention.&rdquo;</p>"},{"id":"b0099e2a-099c-4169-bbcd-1c9e25059db1","content":"<p>&ldquo;Many questions remain about Lumumba&rsquo;s ultimate vision for an independent Congo; without new evidence coming to light, these questions are likely to remain unanswered.&rdquo;</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["1f5290cc-1138-4db1-aafe-3a23129cdca3"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it illustrates the student&rsquo;s claim about some historians viewing Lumumba primarily as a symbol. This quotation argues that Lumumba &ldquo;warrants&rdquo; (or deserves) &ldquo;scholarly attention&rdquo; as a symbol and not for his &ldquo;practical accomplishments&rdquo;&mdash;that is, his actions as prime minister&mdash;which &ldquo;can be passed over quickly,&rdquo; or dismissed as being of comparatively little importance. Thus, the quotation expresses the view that the student criticizes some historians for holding. </p><p>Choice A is incorrect. Although this quotation touches on the difficulty of evaluating Lumumba&rsquo;s legacy, it doesn&rsquo;t address how historians of modern African politics view him as a symbol. Choice B is incorrect. While this quotation mentions Lumumba&rsquo;s political beliefs, it doesn&rsquo;t discuss historians viewing him as a symbol. Choice D is incorrect. This quotation touches on Lumumba&rsquo;s vision for his country, but it doesn&rsquo;t discuss historians viewing him as a symbol. </p>$SATQ$, false, 0, $SATQ$OSP-302-TXT$SATQ$, $SATQ$$SATQ$, $SATQ$159f2b96-276b-4f81-be19-704c3e97a497$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"3f4ab688","external_id":"8ce518f3-dd51-4bc0-8eb6-72b9a8219145","vaultid":"a41c8c55-34f2-4866-a06f-52e6044f56e9","uId":"4dc42c7d-2ead-4dc9-947e-92f222122fd7","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>In a research paper, a student criticizes some historians of modern African politics, claiming that they have evaluated Patrice Lumumba, the first prime minister of what is now the Democratic Republic of the Congo, primarily as a symbol rather than in terms of his actions. </p>","stem":"<p>Which quotation from a work by a historian would best illustrate the student&rsquo;s claim?</p>","answerOptions":[{"id":"0016e186-bd95-482b-bed8-5d55908c036e","content":"<p>&ldquo;Lumumba is a difficult figure to evaluate due to the starkly conflicting opinions he inspired during his life and continues to inspire today.&rdquo;</p>"},{"id":"e835e8ba-6a6f-4f7f-b1aa-8d18567b9627","content":"<p>&ldquo;The available information makes it clear that Lumumba&rsquo;s political beliefs and values were largely consistent throughout his career.&rdquo;</p>"},{"id":"1f5290cc-1138-4db1-aafe-3a23129cdca3","content":"<p>&ldquo;Lumumba&rsquo;s practical accomplishments can be passed over quickly; it is mainly as the personification of Congolese independence that he warrants scholarly attention.&rdquo;</p>"},{"id":"b0099e2a-099c-4169-bbcd-1c9e25059db1","content":"<p>&ldquo;Many questions remain about Lumumba&rsquo;s ultimate vision for an independent Congo; without new evidence coming to light, these questions are likely to remain unanswered.&rdquo;</p>"}],"keys":["1f5290cc-1138-4db1-aafe-3a23129cdca3"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it illustrates the student&rsquo;s claim about some historians viewing Lumumba primarily as a symbol. This quotation argues that Lumumba &ldquo;warrants&rdquo; (or deserves) &ldquo;scholarly attention&rdquo; as a symbol and not for his &ldquo;practical accomplishments&rdquo;&mdash;that is, his actions as prime minister&mdash;which &ldquo;can be passed over quickly,&rdquo; or dismissed as being of comparatively little importance. Thus, the quotation expresses the view that the student criticizes some historians for holding. </p><p>Choice A is incorrect. Although this quotation touches on the difficulty of evaluating Lumumba&rsquo;s legacy, it doesn&rsquo;t address how historians of modern African politics view him as a symbol. Choice B is incorrect. While this quotation mentions Lumumba&rsquo;s political beliefs, it doesn&rsquo;t discuss historians viewing him as a symbol. Choice D is incorrect. This quotation touches on Lumumba&rsquo;s vision for his country, but it doesn&rsquo;t discuss historians viewing him as a symbol. </p>","parenttemplatename":"OSP-302-TXT","parenttemplateid":"","templateclusterid":"159f2b96-276b-4f81-be19-704c3e97a497","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959334,"updateDate":1691007959334}$SATQ$::jsonb, 1691007959334, 1691007959334),
    ($SATQ$3f7f35ea$SATQ$, $SATQ$30cea239-0ff9-42ad-9d98-d405e1b9cdd4$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>&ldquo;The Bet&rdquo; is an 1889 short story by Anton Chekhov. In the story, a banker is described as being very upset about something: <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which quotation from &ldquo;The Bet&rdquo; most effectively illustrates the claim?</p>$SATQ$, $SATQ$[{"id":"92681853-5745-44cf-ab98-2baa08e0b93c","content":"<p>&ldquo;Then the banker cautiously broke the seals off the door and put the key in the keyhole.&rdquo;</p>"},{"id":"4b6db149-990d-469b-aa8f-364c6e110143","content":"<p>&ldquo;It struck three o&rsquo;clock, the banker listened; everyone was asleep in the house and nothing could be heard outside but the rustling of the chilled trees.&rdquo;</p>"},{"id":"3e0862fe-78c9-4f59-b857-d835bdb072a4","content":"<p>&ldquo;The banker, spoilt and frivolous, with millions beyond his reckoning, was delighted at the bet.&rdquo;</p>"},{"id":"7f26e865-f725-4c09-83da-e4d0301975c2","content":"<p>&ldquo;When [the banker] got home he lay on his bed, but his tears and emotion kept him for hours from sleeping.&rdquo;</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["7f26e865-f725-4c09-83da-e4d0301975c2"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because it most effectively uses a quotation from "The Bet" to illustrate the claim that the banker was very upset about something. The quotation indicates that the banker shed tears, which suggests that he was likely unhappy about something, and that his emotions were so strong that they kept him from sleeping for hours. These details suggest that the banker was very upset.</p><p>Choice A is incorrect because this quotation mainly describes the banker cautiously unlocking a door; it doesn&rsquo;t suggest that he was particularly upset about anything. Choice B is incorrect because this quotation doesn&rsquo;t mention whether the banker was experiencing any particularly strong negative feelings; instead, the quotation focuses on the quietness of the setting. Choice C is incorrect because this quotation states that the banker was feeling "delighted," not that he was upset.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"3f7f35ea","external_id":"30cea239-0ff9-42ad-9d98-d405e1b9cdd4","vaultid":null,"uId":"f4bd6094-0a4f-4504-b95f-733daf1c67cd","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>&ldquo;The Bet&rdquo; is an 1889 short story by Anton Chekhov. In the story, a banker is described as being very upset about something: <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which quotation from &ldquo;The Bet&rdquo; most effectively illustrates the claim?</p>","answerOptions":[{"id":"92681853-5745-44cf-ab98-2baa08e0b93c","content":"<p>&ldquo;Then the banker cautiously broke the seals off the door and put the key in the keyhole.&rdquo;</p>"},{"id":"4b6db149-990d-469b-aa8f-364c6e110143","content":"<p>&ldquo;It struck three o&rsquo;clock, the banker listened; everyone was asleep in the house and nothing could be heard outside but the rustling of the chilled trees.&rdquo;</p>"},{"id":"3e0862fe-78c9-4f59-b857-d835bdb072a4","content":"<p>&ldquo;The banker, spoilt and frivolous, with millions beyond his reckoning, was delighted at the bet.&rdquo;</p>"},{"id":"7f26e865-f725-4c09-83da-e4d0301975c2","content":"<p>&ldquo;When [the banker] got home he lay on his bed, but his tears and emotion kept him for hours from sleeping.&rdquo;</p>"}],"keys":["7f26e865-f725-4c09-83da-e4d0301975c2"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because it most effectively uses a quotation from \"The Bet\" to illustrate the claim that the banker was very upset about something. The quotation indicates that the banker shed tears, which suggests that he was likely unhappy about something, and that his emotions were so strong that they kept him from sleeping for hours. These details suggest that the banker was very upset.</p><p>Choice A is incorrect because this quotation mainly describes the banker cautiously unlocking a door; it doesn&rsquo;t suggest that he was particularly upset about anything. Choice B is incorrect because this quotation doesn&rsquo;t mention whether the banker was experiencing any particularly strong negative feelings; instead, the quotation focuses on the quietness of the setting. Choice C is incorrect because this quotation states that the banker was feeling \"delighted,\" not that he was upset.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323045,"updateDate":1730147323045}$SATQ$::jsonb, 1730147323045, 1730147323045),
    ($SATQ$3fc06a91$SATQ$, $SATQ$857c3b1f-07bb-491a-84c5-c45a5f28b850$SATQ$::uuid, $SATQ$1dcda6d0-3c08-4e0c-9056-7c5b233e6bac$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p><figure class="table"><table class="gdr"><caption style="caption-side: top;"><p style="text-align: center;">Employment by Sector in France and the United States, 1800&ndash;2012 (% of total employment)</p></caption><thead><tr><th scope="col" style="text-align: center; vertical-align: bottom;">Year</th><th scope="col" style="text-align: center; vertical-align: bottom;">Agriculture in France</th><th scope="col" style="text-align: center; vertical-align: bottom;">Manufacturing in France</th><th scope="col" style="text-align: center; vertical-align: bottom;">Services in France</th><th scope="col" style="text-align: center; vertical-align: bottom;">Agriculture in US</th><th scope="col" style="text-align: center; vertical-align: bottom;">Manufacturing in US</th><th scope="col" style="text-align: center; vertical-align: bottom;">Services in US</th></tr></thead><tbody><tr><th scope="row" style="text-align: center;">1800</th><td style="text-align: center;">64</td><td style="text-align: center;">22</td><td style="text-align: center;">14</td><td style="text-align: center;">68</td><td style="text-align: center;">18</td><td style="text-align: center;">13</td></tr><tr><th scope="row" style="text-align: center;">1900</th><td style="text-align: center;">43</td><td style="text-align: center;">29</td><td style="text-align: center;">28</td><td style="text-align: center;">41</td><td style="text-align: center;">28</td><td style="text-align: center;">31</td></tr><tr><th scope="row" style="text-align: center;">1950</th><td style="text-align: center;">32</td><td style="text-align: center;">33</td><td style="text-align: center;">35</td><td style="text-align: center;">14</td><td style="text-align: center;">33</td><td style="text-align: center;">53</td></tr><tr><th scope="row" style="text-align: center;">2012</th><td style="text-align: center;">3</td><td style="text-align: center;">21</td><td style="text-align: center;">76</td><td style="text-align: center;">2</td><td style="text-align: center;">18</td><td style="text-align: center;">80</td></tr></tbody></table></figure></p>
<p>Rows in table may not add up to 100 due to rounding.</p>
<p>Over the past two hundred years, the percentage of the population employed in the agricultural sector has declined in both France and the United States, while employment in the service sector (which includes jobs in retail, consulting, real estate, etc.) has risen. However, this transition happened at very different rates in the two countries. This can be seen most clearly by comparing the employment by sector in both countries in <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most effectively uses data from the table to complete the statement?</p>$SATQ$, $SATQ$[{"id":"d843c6aa-1dff-4066-bae9-4188ee3b9b41","content":"<p>1900 with the employment by sector in 1950.</p>"},{"id":"1e9e66ef-dfe8-4c95-849a-f4c271c1f058","content":"<p>1800 with the employment by sector in 2012.</p>"},{"id":"0c2ac6f4-6857-4eaf-b93e-c4f099931cf0","content":"<p>1900 with the employment by sector in 2012.</p>"},{"id":"22e510ea-a3ce-42dd-ab8a-360bf1d0ca27","content":"<p>1800 with the employment by sector in 1900.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["d843c6aa-1dff-4066-bae9-4188ee3b9b41"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it presents data from the table that most effectively complete the statement about the rates at which employment shifted in France and the United States. The text states that over the last two hundred years employment in the agricultural sector has declined while employment in the service sector has risen in both France and the US, and the data from the table reflect these trends. The text asserts, however, that the transition from agriculture to services &ldquo;happened at very different rates in the two countries.&rdquo; This assertion is best supported by a comparison of data from 1900 and 1950: the table shows that in those years, employment in agriculture went from 43% to 32% in France (a decline of 11 percentage points) and from 41% to 14% in the US (a decline of 27 percentage points), and that employment in services went from 28% to 35% in France (an increase of 7 percentage points) and from 31% to 53% in the US (an increase of 22 percentage points). In other words, the rate of change was greater in the US than in France for both sectors. </p><p>Choice B is incorrect because comparing the data for 1800 and 2012 would suggest a similar rate of change in the two countries, not very different rates: employment in agriculture went from 64% in 1800 to 3% in 2012 in France, which is close to the change from 68% in 1800 to 2% in 2012 in the US, while employment in services went from 14% in 1800 to 76% in 2012 in France, which is close to the change from 13% in 1800 to 80% in 2012 in the US. Choice C is incorrect because comparing the data for 1900 and 2012 would suggest a similar rate of change in the two countries rather than very different rates: employment in agriculture went from 43% in 1900 to 3% in 2012 in France, which is close to the change from 41% in 1900 to 2% in 2012 in the US, while employment in services went from 28% in 1900 to 76% in 2012 in France, which is close to the change from 31% in 1900 to 80% in 2012 in the US. Choice D is incorrect because comparing the data for 1800 and 1900 would suggest a similar rate of change in the two countries, not very different rates: employment in agriculture went from 64% in 1800 to 43% in 1900 in France, which is fairly close to the change from 68% in 1800 to 41% in 1900 in the US, while employment in services went from 14% in 1800 to 28% in 1900 in France, which is close to the change from 13% in 1800 to 31% in 1900 in the US. </p>$SATQ$, false, 0, $SATQ$OSP-513-QUA$SATQ$, $SATQ$$SATQ$, $SATQ$bbe0afd7-0fb6-4eec-a4f5-185e11b8108a$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"3fc06a91","external_id":"857c3b1f-07bb-491a-84c5-c45a5f28b850","vaultid":"1dcda6d0-3c08-4e0c-9056-7c5b233e6bac","uId":"3fa558c8-c51a-44cb-8782-4f3c425028a1","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p><figure class=\"table\"><table class=\"gdr\"><caption style=\"caption-side: top;\"><p style=\"text-align: center;\">Employment by Sector in France and the United States, 1800&ndash;2012 (% of total employment)</p></caption><thead><tr><th scope=\"col\" style=\"text-align: center; vertical-align: bottom;\">Year</th><th scope=\"col\" style=\"text-align: center; vertical-align: bottom;\">Agriculture in France</th><th scope=\"col\" style=\"text-align: center; vertical-align: bottom;\">Manufacturing in France</th><th scope=\"col\" style=\"text-align: center; vertical-align: bottom;\">Services in France</th><th scope=\"col\" style=\"text-align: center; vertical-align: bottom;\">Agriculture in US</th><th scope=\"col\" style=\"text-align: center; vertical-align: bottom;\">Manufacturing in US</th><th scope=\"col\" style=\"text-align: center; vertical-align: bottom;\">Services in US</th></tr></thead><tbody><tr><th scope=\"row\" style=\"text-align: center;\">1800</th><td style=\"text-align: center;\">64</td><td style=\"text-align: center;\">22</td><td style=\"text-align: center;\">14</td><td style=\"text-align: center;\">68</td><td style=\"text-align: center;\">18</td><td style=\"text-align: center;\">13</td></tr><tr><th scope=\"row\" style=\"text-align: center;\">1900</th><td style=\"text-align: center;\">43</td><td style=\"text-align: center;\">29</td><td style=\"text-align: center;\">28</td><td style=\"text-align: center;\">41</td><td style=\"text-align: center;\">28</td><td style=\"text-align: center;\">31</td></tr><tr><th scope=\"row\" style=\"text-align: center;\">1950</th><td style=\"text-align: center;\">32</td><td style=\"text-align: center;\">33</td><td style=\"text-align: center;\">35</td><td style=\"text-align: center;\">14</td><td style=\"text-align: center;\">33</td><td style=\"text-align: center;\">53</td></tr><tr><th scope=\"row\" style=\"text-align: center;\">2012</th><td style=\"text-align: center;\">3</td><td style=\"text-align: center;\">21</td><td style=\"text-align: center;\">76</td><td style=\"text-align: center;\">2</td><td style=\"text-align: center;\">18</td><td style=\"text-align: center;\">80</td></tr></tbody></table></figure></p>\n<p>Rows in table may not add up to 100 due to rounding.</p>\n<p>Over the past two hundred years, the percentage of the population employed in the agricultural sector has declined in both France and the United States, while employment in the service sector (which includes jobs in retail, consulting, real estate, etc.) has risen. However, this transition happened at very different rates in the two countries. This can be seen most clearly by comparing the employment by sector in both countries in <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most effectively uses data from the table to complete the statement?</p>","answerOptions":[{"id":"d843c6aa-1dff-4066-bae9-4188ee3b9b41","content":"<p>1900 with the employment by sector in 1950.</p>"},{"id":"1e9e66ef-dfe8-4c95-849a-f4c271c1f058","content":"<p>1800 with the employment by sector in 2012.</p>"},{"id":"0c2ac6f4-6857-4eaf-b93e-c4f099931cf0","content":"<p>1900 with the employment by sector in 2012.</p>"},{"id":"22e510ea-a3ce-42dd-ab8a-360bf1d0ca27","content":"<p>1800 with the employment by sector in 1900.</p>"}],"keys":["d843c6aa-1dff-4066-bae9-4188ee3b9b41"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it presents data from the table that most effectively complete the statement about the rates at which employment shifted in France and the United States. The text states that over the last two hundred years employment in the agricultural sector has declined while employment in the service sector has risen in both France and the US, and the data from the table reflect these trends. The text asserts, however, that the transition from agriculture to services &ldquo;happened at very different rates in the two countries.&rdquo; This assertion is best supported by a comparison of data from 1900 and 1950: the table shows that in those years, employment in agriculture went from 43% to 32% in France (a decline of 11 percentage points) and from 41% to 14% in the US (a decline of 27 percentage points), and that employment in services went from 28% to 35% in France (an increase of 7 percentage points) and from 31% to 53% in the US (an increase of 22 percentage points). In other words, the rate of change was greater in the US than in France for both sectors. </p><p>Choice B is incorrect because comparing the data for 1800 and 2012 would suggest a similar rate of change in the two countries, not very different rates: employment in agriculture went from 64% in 1800 to 3% in 2012 in France, which is close to the change from 68% in 1800 to 2% in 2012 in the US, while employment in services went from 14% in 1800 to 76% in 2012 in France, which is close to the change from 13% in 1800 to 80% in 2012 in the US. Choice C is incorrect because comparing the data for 1900 and 2012 would suggest a similar rate of change in the two countries rather than very different rates: employment in agriculture went from 43% in 1900 to 3% in 2012 in France, which is close to the change from 41% in 1900 to 2% in 2012 in the US, while employment in services went from 28% in 1900 to 76% in 2012 in France, which is close to the change from 31% in 1900 to 80% in 2012 in the US. Choice D is incorrect because comparing the data for 1800 and 1900 would suggest a similar rate of change in the two countries, not very different rates: employment in agriculture went from 64% in 1800 to 43% in 1900 in France, which is fairly close to the change from 68% in 1800 to 41% in 1900 in the US, while employment in services went from 14% in 1800 to 28% in 1900 in France, which is close to the change from 13% in 1800 to 31% in 1900 in the US. </p>","parenttemplatename":"OSP-513-QUA","parenttemplateid":"","templateclusterid":"bbe0afd7-0fb6-4eec-a4f5-185e11b8108a","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959337,"updateDate":1691007959337}$SATQ$::jsonb, 1691007959337, 1691007959337),
    ($SATQ$4025e00c$SATQ$, $SATQ$c1ec7ae5-dfd7-4562-987f-e0248ffbb4b2$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>In the 1950s and &rsquo;60s, plant breeders created shorter varieties of wheat and rice plants with improved yields. Kelly Gillespie, Rex Bernardo, and other plant specialists are building on that work by exploring the development of shorter corn varieties. Greater height can allow individual plants to produce more ears of corn. However, greater height also makes the stalks more likely to snap or be uprooted in strong winds before the corn can be harvested. Because of this trade-off, some plant specialists suggest that shorter corn varieties will actually <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"eda2cd8c-98fd-45a9-8f54-6ada38faa1b2","content":"<p>help improve yields of harvested corn by being more likely to survive in severe winds.</p>"},{"id":"7ccb25a1-ffaa-459b-ae25-1ef137d3a3d7","content":"<p>be more likely to be uprooted due to the weight of the corn on the stalks.</p>"},{"id":"8671228c-7566-44d9-a962-9b9369ca44e4","content":"<p>require more land for planting than short varieties of wheat and rice typically do.</p>"},{"id":"1fded5d7-75e3-4864-b623-d8462e6d6208","content":"<p>begin developing more ears of corn on each plant than the tallest variety of corn currently does.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["eda2cd8c-98fd-45a9-8f54-6ada38faa1b2"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it presents the conclusion that most logically completes the text&rsquo;s discussion about a trade-off in growing shorter varieties of corn. The text explains that plant specialists are working to develop shorter corn varieties in an effort to improve yields. The text points out that although greater height in corn plants can lead to more ears of corn per plant, it also makes the stalks more likely to be damaged by strong winds before there is a chance to harvest the corn. This presents a clear trade-off between potential yield (taller plants producing more ears per plant) and harvest reliability (shorter plants surviving until harvest time). Given this information, it is reasonable to infer that shorter corn varieties, while possibly producing fewer ears per plant, would be more likely to survive until harvest time. This survival advantage would result in improved yields of harvested corn because more plants would remain intact, thus offsetting the potential reduction in ears per shorter plant.</p><p>Choice B is incorrect. According to the text, greater height makes cornstalks vulnerable to snapping or being uprooted in strong winds, implying that taller plants&mdash;not shorter ones&mdash;have greater stability problems. The text provides no basis for inferring that shorter corn varieties would be more likely to be uprooted due to corn weight; in fact, the text suggests the opposite relationship between height and stability. Choice C is incorrect because the text doesn&rsquo;t provide information about the land requirements of either shorter corn varieties or shorter wheat and rice varieties, much less make any comparisons. The text mentions that plant breeders in the 1950s and &rsquo;60s created shorter varieties of wheat and rice with improved yields and that researchers are now exploring shorter corn varieties, but it doesn&rsquo;t compare land-use requirements of these crops. Choice D is incorrect because the idea that shorter cornstalks would yield more ears of corn would contradict the relationship between height and corn production described in the text. The text explicitly states that greater height allows individual plants to produce more ears of corn, which suggests that shorter varieties would produce fewer ears per plant, not more. The text therefore provides no basis for concluding that shorter varieties would begin developing more ears than the taller varieties currently do.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"4025e00c","external_id":"c1ec7ae5-dfd7-4562-987f-e0248ffbb4b2","vaultid":null,"uId":"638c2a44-966e-4bcc-ab63-27eba4980e24","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>In the 1950s and &rsquo;60s, plant breeders created shorter varieties of wheat and rice plants with improved yields. Kelly Gillespie, Rex Bernardo, and other plant specialists are building on that work by exploring the development of shorter corn varieties. Greater height can allow individual plants to produce more ears of corn. However, greater height also makes the stalks more likely to snap or be uprooted in strong winds before the corn can be harvested. Because of this trade-off, some plant specialists suggest that shorter corn varieties will actually <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"eda2cd8c-98fd-45a9-8f54-6ada38faa1b2","content":"<p>help improve yields of harvested corn by being more likely to survive in severe winds.</p>"},{"id":"7ccb25a1-ffaa-459b-ae25-1ef137d3a3d7","content":"<p>be more likely to be uprooted due to the weight of the corn on the stalks.</p>"},{"id":"8671228c-7566-44d9-a962-9b9369ca44e4","content":"<p>require more land for planting than short varieties of wheat and rice typically do.</p>"},{"id":"1fded5d7-75e3-4864-b623-d8462e6d6208","content":"<p>begin developing more ears of corn on each plant than the tallest variety of corn currently does.</p>"}],"keys":["eda2cd8c-98fd-45a9-8f54-6ada38faa1b2"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it presents the conclusion that most logically completes the text&rsquo;s discussion about a trade-off in growing shorter varieties of corn. The text explains that plant specialists are working to develop shorter corn varieties in an effort to improve yields. The text points out that although greater height in corn plants can lead to more ears of corn per plant, it also makes the stalks more likely to be damaged by strong winds before there is a chance to harvest the corn. This presents a clear trade-off between potential yield (taller plants producing more ears per plant) and harvest reliability (shorter plants surviving until harvest time). Given this information, it is reasonable to infer that shorter corn varieties, while possibly producing fewer ears per plant, would be more likely to survive until harvest time. This survival advantage would result in improved yields of harvested corn because more plants would remain intact, thus offsetting the potential reduction in ears per shorter plant.</p><p>Choice B is incorrect. According to the text, greater height makes cornstalks vulnerable to snapping or being uprooted in strong winds, implying that taller plants&mdash;not shorter ones&mdash;have greater stability problems. The text provides no basis for inferring that shorter corn varieties would be more likely to be uprooted due to corn weight; in fact, the text suggests the opposite relationship between height and stability. Choice C is incorrect because the text doesn&rsquo;t provide information about the land requirements of either shorter corn varieties or shorter wheat and rice varieties, much less make any comparisons. The text mentions that plant breeders in the 1950s and &rsquo;60s created shorter varieties of wheat and rice with improved yields and that researchers are now exploring shorter corn varieties, but it doesn&rsquo;t compare land-use requirements of these crops. Choice D is incorrect because the idea that shorter cornstalks would yield more ears of corn would contradict the relationship between height and corn production described in the text. The text explicitly states that greater height allows individual plants to produce more ears of corn, which suggests that shorter varieties would produce fewer ears per plant, not more. The text therefore provides no basis for concluding that shorter varieties would begin developing more ears than the taller varieties currently do.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061191,"updateDate":1755117061191}$SATQ$::jsonb, 1755117061191, 1755117061191),
    ($SATQ$403fb4e4$SATQ$, $SATQ$69ccacae-98b0-4823-a0df-dbc2f84a63fa$SATQ$::uuid, $SATQ$f2ea426f-1af6-41ad-984f-7a4fa5513e20$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<figure class="image"><svg aria-label="Bar graph titled Percentage of Ondo State Small-Scale Farmers Who Are Female, by Main Crop Grown. The horizontal axis is labeled Ondo State region. 3 data categories are shown. The vertical axis is labeled Female farmers as a percentage of total. It ranges from 0 to 60 in increments of 5. Refer to long description." height="596.3408813476562" role="img" viewbox="0 0 400 596.3408813476562" width="400" xmlns="http://www.w3.org/2000/svg"><g data-name="Layer 1" id="ed420550-79eb-48d4-af01-cd27cdd08afd"><defs>
